var scene=UnityEngine.SceneManagement.SceneManager.GetActiveScene();var rs=scene.GetRootGameObjects().SelectMany(g=>g.GetComponentsInChildren<UnityEngine.Renderer>(true)).Where(r=>r.GetComponentInParent<OVRCameraRig>(true)==null&&r.GetComponentInParent<UnityEngine.Canvas>(true)==null && !(r is UnityEngine.SkinnedMeshRenderer)).ToArray();var mats=rs.SelectMany(r=>r.sharedMaterials).Where(m=>m!=null&& !m.shader.name.StartsWith("Cozy Garden/")).Distinct().Select(m=>new{name=m.name,path=UnityEditor.AssetDatabase.GetAssetPath(m),shader=m.shader.name,queue=m.renderQueue,keywords=m.shaderKeywords,users=rs.Where(r=>r.sharedMaterials.Contains(m)).Select(r=>r.name).Distinct().Take(8).ToArray()}).ToArray();var paths=UnityEditor.AssetDatabase.GetDependencies(UnityEditor.AssetDatabase.FindAssets("t:Prefab",new[]{"Assets/Prefabs/TomatoStages"}).Select(UnityEditor.AssetDatabase.GUIDToAssetPath).ToArray(),true);return new{playing=UnityEditor.EditorApplication.isPlaying,materials=mats,cropMaterials=paths.Where(p=>p.EndsWith(".mat")).ToArray()};
